import{_ as s,a0 as u,w as p,s as a,ao as b,I as n,x as e,a1 as t,A as d}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const x=JSON.parse('{"title":"Grub 2：拯救你的 bootloader | LCTT x X-CMD","titleTemplate":false,"description":"Grub 2：拯救你的 bootloader | LCTT (201601) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"Grub 2：拯救你的 bootloader | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"Grub 2：拯救你的 bootloader | LCTT (201601) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201601/20151229 Grub 2--Heal your bootloader","title":"Grub 2：拯救你的 bootloader","tag":"201601","desc":""},"relativePath":"201601/20151229 Grub 2--Heal your bootloader.md","filePath":"[post].md"}'),i={name:"201601/20151229 Grub 2--Heal your bootloader.md"};function g(l,o,c,m,G,h){const r=u("Link");return p(),a("div",null,[o[13]||(o[13]=b(`<h1 id="grub-2-拯救你的-bootloader" tabindex="-1">Grub 2：拯救你的 bootloader <a class="header-anchor" href="#grub-2-拯救你的-bootloader" aria-label="Permalink to “Grub 2：拯救你的 bootloader”">​</a></h1><p><strong>沒有什麼事情比 bootloader 壞掉更讓氣人的了。充分發揮 Grub 2 的作用，讓 bootloader 安分工作吧。</strong></p><p>為什麼這麼説？</p><ul><li>Grub 2 是最受歡迎的 bootloader ，幾乎用在所有 Linux 發行版上。</li><li>bootloader 是一個至關重要的軟件，但是非常容易損壞。</li><li>Grub 2 是兼具擴展性和靈活性的一款引導加載程序，提供了大量可定製選項。</li></ul><p>Grub 2 是一款精彩的功能強大的軟件。它不是 bootloader 界的一枝獨秀，但卻最受歡迎，幾乎所有主要的桌面發行版都在使用它。 Grub 的工作有兩個。首先，它用一個菜單展示計算機上所有已經安裝的操作系統供你選擇。其次，當你從啓動菜單中選擇了一個 Linux 操作系統， Grub 便加載這個 Linux 的內核。</p><p>你知道，如果使用 Linux ，你就離不開 bootloader 。然而它卻是 Linux 發行版內部最鮮為人知的部分。在這篇文章裏，我們將帶你熟悉 Grub 2 一些著名的特性，強化你相關技能，使你在 bootloader 跑飛的時候能夠自行處理。</p><p>Grub 2 最重要的部分是一堆文本文件和兩個腳本文件。首先需要了解的是 <code>/etc/default/grub</code> 。這是一個文本文件，你可以在裏面設置通用配置變量和 Grub 2 菜單（見下方 “常見用户設置” ）的其它特性。</p><p>Grub 2 另一個重要的部分是 <code>/etc/grub.d</code> 文件夾。定義每個菜單項的所有腳本都放置在這裏。這些腳本的名稱必須有兩位的數字前綴。其目的是，在構建 Grub 2 菜單時定義腳本的執行順序以及相應菜單項的順序。文件 <code>00_header</code> 首先被讀取，負責解析 <code>/etc/default/grub</code> 配置文件。然後是 Linux 內核的菜單項，位於 <code>10_linux</code> 文件中。這個腳本在默認的 <code>/boot</code> 分區為每個內核創建一個正規菜單項和一個恢復菜單項。</p><p>緊接着的是為第三方應用所用的腳本，如 <code>30_os-prober</code> 和 <code>40_custom</code> 。 <strong>os-prober</strong> 腳本為內核和其它分區裏的操作系統創建菜單項。它能識別安裝的 Linux、 Windows、 BSD 以及 Mac OS X 。 如果你的硬盤佈局比較獨特，使得 <strong>os-prober</strong> 無法找到已經安裝的發行版，你可以在 <code>40_custom</code> 文件（見下方 “添加自定義菜單項”）中添加菜單項。</p><p><strong>Grub</strong> 2 不需要你手動維護你的啓動選項的配置文件：取而代之的是使用 <code>grub2-mkconfig</code> 命令產生 <code>/boot/grub/grub.cfg</code> 文件。這個功能會解析 <code>/etc/grub.d</code> 目錄中的腳本以及 <code>/etc/default/grub</code> 設置文件來定義你的設置情況。</p><p>###圖形化的引導修復###</p><p>多虧了 Boot Repair 應用，只需要點擊按鈕，Grub 2 許許多多的問題都能輕易解決。這個漂亮小巧的應用有一個直觀的用户界面，可以掃描並識別多種硬盤佈局和分區方案，還能發現並正確識別安裝在其中的操作系統。這個應用可以處理傳統計算機裏的主引導記錄（Master Boot Record） (MBR)，也可以處理新型 UEFI 計算機中的 GUID 分區表（GUID Partition Table)（GPT）。</p><p>Boot Repair 最簡單的使用方式是安裝到 Live Ubuntu 會話中。在一個 bootloader 損壞的機器上啓動 Ubuntu Live 發行版，先通過添加它的 PPA 版本庫來安裝 Boot Repair ，命令如下：</p><pre><code>sudo add-apt-repository ppa:yannubuntu/Boot Repair
</code></pre><p>然後刷新版本庫列表：</p><pre><code>sudo apt-get update
</code></pre><p>安裝應用，如下：</p><pre><code>sudo apt-get install -y Boot Repair
</code></pre><p>安裝完畢後就啓動應用。在顯示它的界面（由一對按鍵組成）之前將會掃描你的硬盤。根據工具的指示，只需按下 Recommended Repair（推薦的修復）按鈕，即可修復大部分壞掉的 bootloader 。修復 bootloader 之後，這個工具會輸出一個短小的 URL ，你應該把它記錄下來。這個 URL 包含了硬盤詳盡的信息：分區信息以及重要的 Grub 2 文件（如 <code>/etc/default/grub</code> 和 <code>/boot/grub/grub.cfg</code> ）的內容。如果工具不能解決 bootloader 的問題，可以把你這個 URL 共享在你的發行版的論壇上，讓其他人可以分析你的硬盤佈局以便給你建議。</p><p><img src="http://www.linuxvoice.com/wp-content/uploads/2015/10/boot-repair-large.jpg" alt=""></p><p><em>Boot Repair 也可以讓你定製 Grub 2 的選項。</em></p><h3 id="bootloader-急救" tabindex="-1">Bootloader 急救 <a class="header-anchor" href="#bootloader-急救" aria-label="Permalink to “Bootloader 急救”">​</a></h3><p>Grub 2 引導問題會讓系統處於幾種不同狀態。屏幕（如你所想，本該顯示 bootloader 菜單的地方）所展示的文本會指示出系統的當前狀態。如果系統中止於 <strong>grub&gt;</strong> 提示符，表明 Grub 2 模組已經被加載，但是找不到 <strong>grub.cfg</strong> 文件。當前是完全版的 Grub 2 命令列 shell，你可以通過多種方式解決此問題。如果你看到的是 <strong>grub rescue&gt;</strong> 提示符，表明 bootloader 不能找到 Grub 2 模組或者找不到任何引導文件（ boot files ）。然而，如果你的屏幕只顯示 ‘GRUB’ 一詞，表明 bootloader 找不到通常位於主引導記錄（ Master Boot Record ）裏的最基本的信息。</p><p>你可以通過使用 live CD 或者在 Grub 2 shell 中修正此類錯誤。如果你夠幸運， bootloader 出現了 <strong>grub&gt;</strong> 提示符，你就能獲得 Grub 2 shell 的支配權，來幫助你排錯。</p><p>接下來幾個命令工作在 <strong>grub&gt;</strong> 和 <strong>grub rescue&gt;</strong> 提示符下。 <strong>set pager=1</strong> 命令設置顯示分頁（ pager ），防止文本在屏幕上一滾而過。你還可以使用 <strong>ls</strong> 命令列出 Grub 識別出的所有分區，如下：</p><pre><code>grub&gt; ls
(hd0) (hd0,msdos5) (hd0,msdos6) (hd1,msdos1)
</code></pre><p>如你所見，這個命令列出分區的同時一併列出了分區表方案（即 msdos）。</p><p>你還可以在每個分區上面使用 <strong>ls</strong> 來查找你的根文件系統：</p><pre><code>grub&gt; ls (hd0,5)/
lost+found/ var/ etc/ media/ bin/ initrd.gz
boot/ dev/ home/ selinux/ srv/ tmp/ vmlinuz
</code></pre><p>你可以不寫上分區名的 <strong>msdos</strong> 部分。同樣，如果你忘記了尾部的斜槓（ trailing slash ）只輸入 <code>ls (hd0,5)</code> ，那你將獲得分區的信息，比如文件系統類型、總體大小和最後修改時間。如果你有多個分區，可以使用 <code>cat</code> 讀取 <code>/etc/issue</code> 文件中的內容，來確定發行版，格式如 <code>cat (hd0,5)/etc/issue</code> 。</p><p>假設你在 <strong>(hd0,5)</strong> 中找到根文件系統，請確保它包含 <code>/boot/grub</code> 目錄，以及你想引導進入的內核鏡像，如 <strong>vmlinuz-3.13.0-24-generic</strong> 。此時輸入以下命令：</p><pre><code>grub&gt; set root=(hd0,5)
grub&gt; linux /boot/vmlinuz-3.13.0-24-generic root=/dev/sda5
grub&gt; initrd /boot/initrd.img-3.13.0-24-generic
</code></pre><p>第一個命令把 Grub 指向我們想引導進入的發行版所在的分區。接着第二個命令告知 Grub 內核鏡像在分區中的位置，以及根文件系統的位置。最後一行設置虛擬文件系統（ initial ramdisk ）文件的位置。你可以使用 tab 補全功能補全內核名字和虛擬文件系統（ initrd: initial ramdisk ）的名字，節省時間和精力。</p><p>輸入完畢，在下一個 <strong>grub&gt;</strong> 提示符後輸入 <code>boot</code> ， Grub 將會引導進入指定的操作系統。</p><p>如果你在 <strong>grub rescue&gt;</strong> 提示符下，情況會有些許不同。因為 bootloader 未能夠找到並加載任何必需的模組，你需要手動添加這些模組：</p><pre><code>grub rescue&gt; set root=(hd0,5)
grub rescue&gt; insmod (hd0,5)/boot/grub/normal.mod
grub rescue&gt; normal
grub&gt; insmod linux
</code></pre><p>如上所示，跟之前一樣，使用 <code>ls</code> 命令列出所有分區之後，使用 <code>set</code> 命令標記起來。然後添加 <strong>normal</strong> 模組，此模組激活時將會恢復到標準 <strong>grub&gt;</strong> 模式。如果 linux 模組沒加載，接下來的命令會進行添加。如果這個模組已經加載，你可以跟之前一樣，把引導加載程序指向內核鏡像和虛擬文件系統（ initrd ）文件，然後使用 <code>boot</code> 啓動發行版，完美收官。</p><p>一旦成功啓動發行版，別忘了為 Grub 重新產生新的配置文件，使用</p><pre><code>grub-mkconfig -o /boot/grub/grub.cfg
</code></pre><p>命令。你還需要往 MBR 裏安裝一份 bootloader 的拷貝，使用</p><pre><code>sudo grub2-install /dev/sda
</code></pre><p>命令。</p><p><img src="http://www.linuxvoice.com/wp-content/uploads/2015/10/grub2-cfg-large.jpg" alt=""></p><p><em>想要禁用 <code>/etc/grub.d</code> 目錄下的腳本，你只需移除其可執行位，比如使用 <code>chmod -x /etc/grub.d/20_memtest86+</code> 就能將 ‘Memory Test’ 選項從菜單中移除。</em></p><h3 id="grub-2-和-uefi" tabindex="-1">Grub 2 和 UEFI <a class="header-anchor" href="#grub-2-和-uefi" aria-label="Permalink to “Grub 2 和 UEFI”">​</a></h3><p>在支持 UEFI 的機器（最近幾年上市的機器大部分都是）調試壞掉的 Grub 2 增加了另一複雜的層次。恢復安裝在 UEFI 機器上的 <strong>Grub 2</strong> 的和安裝在非 UEFI 機器上的並沒多大區別，只是新的固件處理方式不一樣，從而導致了很多種恢復結果。</p><p>對於基於 UEFI 的系統，不要在 MBR 上安裝任何東西。相反，你要在 EFI 系統分區（EFI System Partition）（ ESP ）裏安裝 Linux EFI bootloader，並且藉助工具把它設置為 EFI 的默認啓動程序，這個工具對於 Linux 用户是 <code>efibootmgr</code> ，對於 window 用户則是 <code>bcdedit</code> 。</p><p>照目前情況看，在安裝任何與 Windows 8 兼容的主流桌面 Linux 發行版前，應該正確安裝好 Grub 2。然而，如果 bootloader 損壞，你可以使用 live 發行版修復機器。在啓動 live 介質之時，請確保是以 UEFI 模式啓動。計算機每個可移動驅動器的啓動菜單將會有兩個： 一個普通的和一個以 EFI 標記的。使用後者會用到 <strong>/sys/firmware/efi/</strong> 文件中的 EFI 變量。</p><p>在 live 環境中，掛載教程前面所提的安裝掛掉系統的根文件系統。除此之外，還需要掛載 ESP 分區。假設分區是 <strong>/dev/sda1</strong> ，你可以如下所示掛載：</p><pre><code>sudo mount /dev/sda1 /mnt/boot/efi
</code></pre><p>接着在 chroot 到安裝完畢的發行版前之前，使用 <code>modprobe efivars</code> 加載 <strong>efivars</strong> 模組。</p><p>在這裏， Fedora 用户可以使用如下命令重新安裝 bootloader</p><pre><code>yum reinstall grub2-efi shim
</code></pre><p>但在此之前，需要使用</p><pre><code>grub2-mkconfig -o /boot/grub2/grub.cfg
</code></pre><p>來產生新的配置文件。 Ubuntu 用户則改用以下命令</p><pre><code>apt-get install --reinstall grub-efi-amd64
</code></pre><p>一旦 bootloader 正確就位，退出 chroot ，卸載所有分區，重啓到 Grub 2 菜單。</p><h3 id="夥計-我的-grub-哪去了" tabindex="-1">夥計，我的 Grub 哪去了？ <a class="header-anchor" href="#夥計-我的-grub-哪去了" aria-label="Permalink to “夥計，我的 Grub 哪去了？”">​</a></h3><p>Grub 2 最好的特性是可以隨時重新安裝。因此，當其它像 Windows 之類的系統用它們自己的 bootloader 替換後，導致 Grub 2 丟失，你可以使用 live 發行版，寥寥數步即可重裝 Grub 。假設你在 <code>/dev/sda5</code> 安裝了一個發行版，若要重裝 Grub ，你只需首先使用以下命令為發行版創建一個掛載目錄：</p><pre><code>sudo mkdir -p /mnt/distro
</code></pre><p>然後掛載分區，如下：</p><pre><code>mount /dev/sda5 /mnt/distro
</code></pre><p>接着就能重裝 Grub 了，如下：</p><pre><code>grub2-install --root-directory=/mnt/distro /dev/sda
</code></pre><p>這個命令會改寫 <code>/dev/sda</code> 設備上的 MBR 信息，指向當前 Linux 系統，並重寫一些 Grub 2 文件，如 <strong>grubenv</strong> 和 <strong>device.map</strong> 。</p><p>另一個問題常見於裝有多個發行版的計算機上。當你安裝了新的 Linux 發行版，它的 bootloader 應當要能找到所有已經安裝的發行版。一旦不行，只要引導進入新安裝的發行版，並運行</p><pre><code>grub2-mkconfig
</code></pre><p>在運行這個命令之前，請確保啓動菜單中缺失的發行版的 root 分區已經掛載。如果你想添加的發行版有單獨的 <code>/root</code> 和 <code>/home</code> 分區，在運行 <code>grub2-mkconfig</code> 之前，只需掛載包含 <code>/root</code> 的分區。</p><p>雖然 Grub 2 能夠找到大部分發行版，但是在 Ubuntu 中嘗試添加安裝的 Fedora 系統需要額外的一個步驟。如果你以默認設置安裝了 Fedora ，則發行版的安裝器已經創建了 LVM 分區。此時你需要使用發行版的包管理系統安裝 <strong>lvm2</strong> 驅動，如下</p><pre><code>sudo apt-get install lvm2
</code></pre><p>才能使得 Grub 2 的 <code>os-prober</code> 腳本能夠找到並將 Fedora 添加進啓動菜單。</p><h3 id="常見用户設置" tabindex="-1">常見用户設置 <a class="header-anchor" href="#常見用户設置" aria-label="Permalink to “常見用户設置”">​</a></h3><p>Grub 2 有很多可配置變量。 這裏有一些 <code>/etc/default/grub</code> 文件中你最可能會修改到的常見變量。 <strong>GRUB_DEFAULT</strong> 變量指定默認的啓動項，可以設置為數字值，比如 0 ，表示第一個菜單項，或者設置為 “saved” ，將指向上一次啓動時選中的菜單項。 <strong>GRUB_TIMEOUT</strong> 變量指定啓動默認菜單項之前的停留時間。 <strong>GRUB_CMDLINE_LINUX</strong> 列出了要傳遞給所有 Linux 菜單項的內核命令列參數。</p><p>如果 <strong>GRUB_DISABLE_RECOVERY</strong> 變量設置為 <strong>true</strong> ，那麼將不生成恢復模式菜單項。這些菜單項會以單用户模式啓動發行版，這種模式下允許你利用命令列工具修復系統。 <strong>GRUB_GFXMODE</strong> 變量同樣有用，它指定了菜單上文本顯示的分辨率，它可以設置為你的顯卡所支持的任何數值。</p><p><img src="http://www.linuxvoice.com/wp-content/uploads/2015/10/grub2-cli-large.jpg" alt=""></p><p><em>Grub 2 有個命令列模式，通過在 bootloader 菜單上按 C 進入。</em></p><h3 id="徹底的修復" tabindex="-1">徹底的修復 <a class="header-anchor" href="#徹底的修復" aria-label="Permalink to “徹底的修復”">​</a></h3><p>如果 <code>grub2-install</code> 命令不能正常運作，使得你無法引導進入 Linux ，你需要完整地重裝以及重新配置 bootloader 。為此目的，需要用到強大的 <strong>chroot</strong> 功能將運行環境從 live CD 環境切換至我們想修復的 Linux 的安裝位置。任何擁有 <strong>chroot</strong> 工具的 Linux live CD 都可以實現這個目的。不過需要確保 live 介質的系統架構和硬盤上系統的架構一致。因此當你希望 <strong>chroot</strong> 到 64 位系統，你必須使用 amd64 live 發行版。</p><p>啓動進入 live 發行版之後，首先需要檢查機器上的分區。使用 <code>fdisk -l</code> 列出磁盤上所有分區，記錄你想修復的 Grub 2 系統所在的分區。</p><p>假設我們希望從安裝在 <code>/dev/sda5</code> 中的發行版中恢復 bootloader 。啓動終端使用如下命令掛載分區：</p><pre><code>sudo mount /dev/sda5 /mnt
</code></pre><p>此時需要綁定（bind）Grub 2 bootloader 需要進入的目錄，以便檢測其它操作系統：</p><pre><code>$ sudo mount --bind /dev /mnt/dev
$ sudo mount --bind /dev/pts /mnt/dev/pts
$ sudo mount --bind /proc /mnt/proc
$ sudo mount --bind /sys /mnt/sys
</code></pre><p>此時可以離開 live 環境進入安裝在 <strong>/dev/sda5</strong> 分區中的發行版了，通過 <strong>chroot</strong> ：</p><pre><code>$ sudo chroot /mnt /bin/bash
</code></pre><p>現在可以安裝、檢測、以及升級 Grub 了，跟之前一樣，使用</p><pre><code>sudo grub2-install /dev/sda
</code></pre><p>命令來重裝 bootloader 。因為 <strong>grub2-install</strong> 命令不能創建<strong>grub.cfg</strong> 文件，需要手動創建，如下</p><pre><code>sudo grub-mkconfig -o /boot/grub/grub.cfg
</code></pre><p>這樣應該就可以了。現在你就有了 Grub 2 的一份全新拷貝，羅列了機器上所有的操作系統和發行版。在重啓電腦之前，你需要依次退出 chroot 系統，卸載所有分區，如下所示：</p><pre><code>$ exit
$ sudo umount /mnt/sys
$ sudo umount /mnt/proc
$ sudo umount /mnt/dev/pts
$ sudo umount /mnt/dev
$ sudo umount /mnt
</code></pre><p>現在你可以安全地重啓電腦了，而它應該會回退到 Grub 2 的控制之中，你已經修好了這個 bootloader。</p><h3 id="添加自定義菜單項" tabindex="-1">添加自定義菜單項 <a class="header-anchor" href="#添加自定義菜單項" aria-label="Permalink to “添加自定義菜單項”">​</a></h3><p>如果希望往 bootloader 菜單裏添加菜單項，你需要在 <strong>40_custom</strong> 文件裏添加一個啓動段（ boot stanza ）。例如，你可以使用它展示一個菜單項來啓動安裝在可移動 USB 驅動裏的 Linux 發行版。假設你的 USB 驅動器是 <strong>sdb1</strong> ，並且 vmlinuz 內核鏡像和虛擬文件系統（ initrd ）都位於根 (/)目錄下，在 <strong>40_custom</strong> 文件中添加以下內容：</p><pre><code>menuentry “Linux on USB” {
	set root=(hd1,1)
	linux /vmlinuz root=/dev/sdb1 ro quiet splash
	initrd /initrd.img
}
</code></pre><p>相比使用設備和分區名，使用它們的 UUID 可以獲得更精確結果，比如</p><pre><code>set root=UUID=54f22dd7-eabe
</code></pre><p>使用</p><pre><code>sudo blkid
</code></pre><p>來獲得所有已連接的驅動器和分區的 UUID 。你還可以為你磁盤上沒被 os-prober 腳本找到的發行版添加菜單項，只要你知道該發行版的安裝位置以及其內核和虛擬文件系統（ initrd ）的位置即可。</p><hr>`,102)),n("p",null,[o[1]||(o[1]=e("via: ",-1)),t(r,{href:"https://www.linuxvoice.com/grub-2-heal-your-bootloader/"},{default:d(()=>[...o[0]||(o[0]=[e("https://www.linuxvoice.com/grub-2-heal-your-bootloader/",-1)])]),_:1})]),n("p",null,[o[5]||(o[5]=e("作者：",-1)),t(r,{href:"https://www.linuxvoice.com/author/mayank/"},{default:d(()=>[...o[2]||(o[2]=[e("Mayank Sharma",-1)])]),_:1}),o[6]||(o[6]=e(" 譯者：",-1)),t(r,{href:"https://github.com/soooogreen"},{default:d(()=>[...o[3]||(o[3]=[e("soooogreen",-1)])]),_:1}),o[7]||(o[7]=e(" 校對：",-1)),t(r,{href:"https://github.com/wxy"},{default:d(()=>[...o[4]||(o[4]=[e("wxy",-1)])]),_:1})]),n("p",null,[o[10]||(o[10]=e("本文由 ",-1)),t(r,{href:"https://github.com/LCTT/TranslateProject"},{default:d(()=>[...o[8]||(o[8]=[e("LCTT",-1)])]),_:1}),o[11]||(o[11]=e(" 原創編譯，",-1)),t(r,{href:"https://linux.cn/"},{default:d(()=>[...o[9]||(o[9]=[e("Linux中國",-1)])]),_:1}),o[12]||(o[12]=e(" 榮譽推出",-1))])])}const L=s(i,[["render",g]]);export{x as __pageData,L as default};
